	const out = new Complex64Array( 3 );

	crotg.ndarray( 0.0, 0.0, 2.0, 0.0, out, 1, '10' ); // $ExpectError
	crotg.ndarray( 0.0, 0.0, 2.0, 0.0, out, 1, true ); // $ExpectError
	crotg.ndarray( 0.0, 0.0, 2.0, 0.0, out, 1, false ); // $ExpectError
